mapper.select:
SELECT cwf.*, sbc.name AS branch_company_name, founder.name AS founder_name, cet.name AS expense_type_name FROM contract_wage_fee cwf LEFT JOIN sys_branch_company sbc ON sbc.bool_delete_enum = FALSE AND sbc.id = cwf.branch_company_id LEFT JOIN contract_expense_type cet ON cet.bool_delete_enum = FALSE AND cet.id = cwf.expense_type_id LEFT JOIN sys_user founder ON founder.bool_delete_enum = FALSE AND founder.id = cwf.founder_id WHERE cwf.bool_delete_enum = FALSE
AND cwf.fill_in_year = #{year}
AND cwf.branch_company_id = #{branchCompanyId}
